// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function testFuzz_property(uint256 amount) public {
        // The first distribution's value is fixed at 2500e18; fuzzing the amount lets us
        // discover any input where the invariant breaks, but getTokens itself uses the
        // contract's `value` state variable.  We instead fuzz the value by setting it
        // directly through a helper?  No, we cannot write to c directly.  So we drive
        // the public entry `getTokens` with the contract's initial value (2500e18).
        // However, to let the fuzzer explore a wider domain, we can adjust the remaining
        // distribution by calling getTokens multiple times?  That would still always use
        // the current `value`.  The bug is deterministic: any successful distribution
        // increments totalRemaining, so after the very first call the invariant is already
        // broken.  We still take a fuzzed parameter to comply with the rule, and use it to
        // vary the caller / ether sent (though value is fixed).
        //
        // We make the fuzzer pick an arbitrary address to call getTokens, and optionally
        // send ether.  The contract's getTokens is payable and does not use msg.value.
        // The only requirement is that the caller is not blacklisted and distribution not
        // finished.  We can use any address.
        address caller = address(uint160(uint256(keccak256(abi.encode(amount)))));
        // ensure caller is not blacklisted (initially false) and not the owner?  owner is
        // not restricted by onlyWhitelist; any non-blacklisted address works.
        // We need to ensure that `value <= totalRemaining` and that distribution is not
        // finished.  Initially totalRemaining is 500000000e18 - 250000000e18 = 250000000e18,
        // value is 2500e18.  So it passes.

        // The invariant we assert: totalDistributed + totalRemaining == totalSupply.
        // In the reference, after the first distribution totalDistributed increases by 2500e18
        // and totalRemaining decreases by 2500e18, so the sum is unchanged.
        // In the mutant, both increase, so the sum becomes totalSupply + 5000e18.
        // We assert the invariant before and after a getTokens call to be robust.

        uint256 initialTotalDistributed = c.totalDistributed();
        uint256 initialTotalRemaining = c.totalRemaining();
        uint256 initialTotalSupply = c.totalSupply();

        // precondition: invariant holds initially (it does in both versions)
        assertTrue(initialTotalDistributed + initialTotalRemaining == initialTotalSupply);

        // perform a distribution
        vm.prank(caller);
        c.getTokens();

        uint256 newTotalDistributed = c.totalDistributed();
        uint256 newTotalRemaining = c.totalRemaining();
        uint256 newTotalSupply = c.totalSupply();

        // The invariant must hold after the distribution.
        assertTrue(newTotalDistributed + newTotalRemaining == newTotalSupply);
    }
}
